UPDATE public.study_materials SET quiz='[{"q":"O patrimonialismo admite confusão entre interesses privados do governante e recursos públicos.","a":true,"why":"Essa confusão é marca do patrimonialismo.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Clientelismo e favorecimento pessoal podem caracterizar práticas patrimonialistas.","a":true,"why":"Relações pessoais se sobrepõem a critérios impessoais.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"No patrimonialismo, o cargo público é necessariamente provido por seleção técnica impessoal.","a":false,"why":"A seleção impessoal é típica da burocracia racional-legal.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"A adoção de regras burocráticas impede automaticamente toda prática patrimonialista.","a":false,"why":"Práticas patrimonialistas podem persistir apesar de normas formais.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-01-patrimonialismo-e-separacao-publico-privado' AND content_status='archived' AND practice_review IS NULL;
UPDATE public.study_materials SET quiz='[{"q":"A burocracia racional-legal fundamenta a autoridade em regras e competências definidas.","a":true,"why":"O cargo é institucional, não patrimônio pessoal.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"A impessoalidade é incompatível com o modelo burocrático.","a":false,"why":"A impessoalidade é uma de suas características.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"O DASP foi criado em 1938 como marco de racionalização da administração federal.","a":true,"why":"O DASP participou da profissionalização e padronização administrativa.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Formalismo excessivo e rigidez podem ser disfunções da burocracia.","a":true,"why":"Procedimentos podem se tornar um fim em si mesmos.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-02-burocracia-e-reforma-de-1930-1938' AND content_status='archived' AND practice_review IS NULL;
UPDATE public.study_materials SET quiz='[{"q":"A administração gerencial valoriza resultados, indicadores e qualidade dos serviços.","a":true,"why":"Seu foco inclui desempenho e atendimento ao cidadão.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"A autonomia gerencial elimina a obrigação de prestar contas.","a":false,"why":"Autonomia exige responsabilização e controles.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"O Plano Diretor da Reforma do Aparelho do Estado de 1995 é referência da reforma gerencial brasileira.","a":true,"why":"O plano impulsionou o debate sobre gestão por resultados.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Administração gerencial significa privatização obrigatória de todas as atividades estatais.","a":false,"why":"A orientação gerencial não implica privatização generalizada.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-03-administracao-gerencial' AND content_status='archived' AND practice_review IS NULL;
UPDATE public.study_materials SET quiz='[{"q":"Órgãos da administração direta têm personalidade jurídica própria.","a":false,"why":"Órgãos integram a pessoa política e não têm personalidade própria.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Desconcentração é a distribuição interna de competências na mesma pessoa jurídica.","a":true,"why":"A criação de órgãos internos não constitui outra pessoa jurídica.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Autarquias são entidades da administração indireta com personalidade jurídica de direito público.","a":true,"why":"São criadas diretamente por lei.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Descentralização e desconcentração são conceitos equivalentes.","a":false,"why":"Descentralização envolve outra pessoa jurídica ou delegação; desconcentração é interna.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-04-administracao-direta-indireta-e-descentralizacao' AND content_status='archived' AND practice_review IS NULL;
UPDATE public.study_materials SET quiz='[{"q":"Planejamento e coordenação estão entre os princípios fundamentais do Decreto-Lei 200/1967.","a":true,"why":"Ambos estão no art. 6º.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"O controle não integra os princípios fundamentais do Decreto-Lei 200/1967.","a":false,"why":"O controle é expressamente previsto no art. 6º.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Delegação de competência e descentralização são sempre a mesma operação.","a":false,"why":"Delegação transfere exercício de atribuições; descentralização tem alcance organizacional distinto.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"O Decreto-Lei 200/1967 trata da organização da Administração Federal.","a":true,"why":"O diploma disciplina a organização administrativa federal.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-05-decreto-lei-n-200-1967-e-organizacao-federal' AND content_status='archived' AND practice_review IS NULL;
UPDATE public.study_materials SET quiz='[{"q":"O controle externo federal é exercido pelo Congresso Nacional com auxílio do TCU.","a":true,"why":"A Constituição estabelece esse arranjo nos arts. 70 e 71.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Ouvidorias e transparência podem contribuir para o controle social.","a":true,"why":"Facilitam acompanhamento e fiscalização pela sociedade.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"Accountability envolve somente divulgar informações, sem responsabilização.","a":false,"why":"Inclui informar, justificar e responder pelas decisões.","tip":"Observe o conceito e os termos absolutos do enunciado."},{"q":"O controle judicial não pode examinar lesão a direitos causada por ato administrativo.","a":false,"why":"A Constituição assegura apreciação judicial de lesão ou ameaça a direito.","tip":"Observe o conceito e os termos absolutos do enunciado."}]'::jsonb, updated_at=now() WHERE slug='pcac-2026-guia-administracao-publica-06-reforma-gerencial-e-controles-institucionais' AND content_status='archived' AND practice_review IS NULL;
COMMIT;
